284	/// Recursively hash-object every file under `dir` into `index_file`, rooted at
285	/// `prefix`. `exclude` is applied only at the top level of `dir` (used to keep
286	/// `config.toml` off the sidecar branch while still committing everything else).
287	fn stage_dir(
288	    repo_root: &Path,
289	    index_file: &Path,
290	    dir: &Path,
291	    prefix: &str,
292	    exclude: &[&str],
293	) -> Result<()> {
294	    for entry in std::fs::read_dir(dir).with_context(|| format!("read_dir {}", dir.display()))? {
295	        let entry = entry?;
296	        let name = entry.file_name();
297	        let name_str = name.to_string_lossy();
298	        if exclude.contains(&name_str.as_ref()) {
299	            continue;
300	        }
301	        let path = entry.path();
302	        let rel = format!("{prefix}/{name_str}");
303	        if path.is_dir() {
304	            stage_dir(repo_root, index_file, &path, &rel, &[])?;
305	        } else {
306	            let sha = hash_object(repo_root, &path)?;
307	            update_index_add(repo_root, index_file, &sha, &rel)?;
308	        }
309	    }
310	    Ok(())
311	}
