313	/// Create the sidecar branch's first commit purely via plumbing — no checkout, no
314	/// working-tree interaction, so a failure here can never leave the repo mid-switch.
315	fn bootstrap_sidecar_branch(repo_root: &Path, branch: &str) -> Result<()> {
316	    let header_path = scratch_path(repo_root, "bootstrap-csv");
317	    std::fs::write(
318	        &header_path,
319	        "id,shortname,description,naive_change,outcomes,attractor_id\n",
320	    )?;
321	    let sha = hash_object(repo_root, &header_path);
322	    let _ = std::fs::remove_file(&header_path);
323	    let sha = sha?;
324	
325	    let index_file = scratch_path(repo_root, "bootstrap-index");
326	    let tree = update_index_add(repo_root, &index_file, &sha, "residual/stressors.csv")
327	        .and_then(|()| write_tree(repo_root, &index_file));
328	    let _ = std::fs::remove_file(&index_file);
329	    let tree = tree?;
330	
331	    let commit = commit_tree(repo_root, &tree, &[], "bootstrap sidecar metadata")?;
332	    update_ref(repo_root, branch, &commit, "")
333	}
