335	/// Materialize a read-only snapshot of `branch`'s `residual/` tree into a scratch
336	/// directory under `.git/`. Read-only from git's perspective (`ls-tree`/`show`) — never
337	/// touches the working tree or index.
338	fn materialize_branch_tree(repo_root: &Path, branch: &str) -> Result<PathBuf> {
339	    if !branch_exists(repo_root, branch)? {
340	        bootstrap_sidecar_branch(repo_root, branch)?;
341	    }
342	
343	    let checkout = repo_root.join(".git").join("residual-sidecar-checkout");
344	    if checkout.exists() {
345	        std::fs::remove_dir_all(&checkout)
346	            .with_context(|| format!("clear {}", checkout.display()))?;
347	    }
348	    std::fs::create_dir_all(&checkout)?;
349	
350	    let list_out = git(repo_root)
351	        .args(["ls-tree", "-r", "--name-only", branch, "--", "residual/"])
352	        .output()
353	        .context("git ls-tree sidecar")?;
354	    if !list_out.status.success() {
355	        bail!(
356	            "git ls-tree failed: {}",
357	            String::from_utf8_lossy(&list_out.stderr)
358	        );
359	    }
360	
361	    let paths = String::from_utf8_lossy(&list_out.stdout);
362	    for rel in paths.lines().filter(|l| !l.is_empty()) {
363	        let show_out = git(repo_root)
364	            .args(["show", &format!("{branch}:{rel}")])
365	            .output()
366	            .with_context(|| format!("git show {branch}:{rel}"))?;
367	        if !show_out.status.success() {
368	            continue;
369	        }
370	        let dest = checkout.join(rel.strip_prefix("residual/").unwrap_or(rel));
371	        if let Some(parent) = dest.parent() {
372	            std::fs::create_dir_all(parent)?;
373	        }
374	        std::fs::write(&dest, &show_out.stdout)?;
375	    }
376	
377	    Ok(checkout)
378	}
