662	/// tip. The only place a per-code-branch metadata branch gets created. Idempotent.
663	pub fn branch_init(
664	    repo_root: &Path,
665	    sidecar: &SidecarConfig,
666	    target_branch: Option<&str>,
667	) -> Result<String> {
668	    if !branch_exists(repo_root, &sidecar.branch)? {
669	        bootstrap_sidecar_branch(repo_root, &sidecar.branch)?;
670	    }
671	    let working = match target_branch {
672	        Some(b) => b.to_string(),
673	        None => current_branch(repo_root)?,
674	    };
675	    let resolved = resolve_branch_name(&sidecar.branch_pattern, &working);
676	    if resolved == sidecar.branch || branch_exists(repo_root, &resolved)? {
677	        return Ok(resolved);
678	    }
679	    let trunk_sha = rev_parse(repo_root, &format!("refs/heads/{}", sidecar.branch))?;
680	    update_ref(repo_root, &resolved, &trunk_sha, "")?;
681	    Ok(resolved)
