52	fn periodic_turn_at(state_path: &Path, turn: u32, text: &str) -> Result<Option<String>> {
53	    let topic = match classify(text) {
54	        Some(topic) => topic,
55	        None => return Ok(None),
56	    };
57	
58	    let mut state = load_state(state_path)?;
59	    if let Some(&last_turn) = state.last_fired_turn.get(topic) {
60	        if turn.saturating_sub(last_turn) < MIN_TURNS_BETWEEN_SAME_TOPIC {
61	            return Ok(None);
62	        }
63	    }
64	
65	    let suggestion = build_suggestion(topic, turn);
66	    if state.last_suggestion == suggestion {
67	        return Ok(None);
68	    }
69	
70	    state.last_fired_turn.insert(topic.to_string(), turn);
71	    state.last_suggestion = suggestion.clone();
