79	/// precise; false negatives (silence) are the safe failure mode per A-20.
80	fn classify(text: &str) -> Option<&'static str> {
81	    let lower = text.to_lowercase();
82	    const TOPICS: &[&str] = &[
83	        guru::TOPIC_ATTRACTORS,
84	        guru::TOPIC_STRESSORS,
85	        guru::TOPIC_PURPOSES,
86	        guru::TOPIC_PERSONAS,
87	        guru::TOPIC_WHOLE_SYSTEM_RESIDUE,
88	        guru::TOPIC_WALK_REMINDER,
89	    ];
90	    for topic in TOPICS {
91	        if lower.contains(topic) || topic_keywords(topic).iter().any(|kw| lower.contains(kw)) {
92	            return Some(topic);
93	        }
94	    }
